const signal = controller.signal;

window.screenLock = null;
window.currentLink = document.URL.split("?")[0].split("#")[0];
window.page = window.location.pathname.split("/").pop();

/**
 * Returns the base URL of the current location. If the hostname is "localhost" or
 * an IP address that matches the IPv4 loopback address (127.0.0.1), the protocol and
 * hostname with the first pathname segment are returned. Otherwise, the origin is returned.
 *
 * @return {string} The base URL.
 */
const baseurl = () => {
    const isLocalhost = window.location.hostname === "localhost" ||
      window.location.hostname === "[::1]" ||
      window.location.hostname.match(/^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/);
    return isLocalhost
      ? `${window.location.protocol}//${window.location.host}/${window.location.pathname.split("/")[1]}`
      : location.origin;
}


/**
 * An object containing functions that determine if the user's device is running
 * certain mobile operating systems.
 *
 * @type {Object}
 */
const isMobile = {
  /**
   * Returns a boolean indicating whether the user's device is running Android.
   *
   * @return {boolean}
   */
  Android: () => navigator.userAgent.match(/Android/i),

  /**
   * Returns a boolean indicating whether the user's device is running BlackBerry.
   *
   * @return {boolean}
   */
  BlackBerry: () => navigator.userAgent.match(/BlackBerry/i),

  /**
   * Returns a boolean indicating whether the user's device is running iOS.
   *
   * @return {boolean}
   */
  iOS: () => navigator.userAgent.match(/iPhone|iPad|iPod/i),

  /**
   * Returns a boolean indicating whether the user's device is running Opera Mini.
   *
   * @return {boolean}
   */
  Opera: () => navigator.userAgent.match(/Opera Mini/i),

  /**
   * Returns a boolean indicating whether the user's device is running Windows.
   *
   * @return {boolean}
   */
  Windows: () => navigator.userAgent.match(/IEMobile/i),

  /**
   * Returns a boolean indicating whether the user's device is running any of the
   * mobile operating systems checked by the other functions in the `isMobile` object.
   *
   * @return {boolean}
   */
  any: () => isMobile.Android() || isMobile.BlackBerry() || isMobile.iOS() || isMobile.Opera() || isMobile.Windows(),
};

const isDesktop = !(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent));

// Function to check internet speed
function checkSpeed() {
    if (navigator.connection) {
        var speed = navigator.connection.downlink;
        console.log(speed + 'Mbps');
    } else if (navigator.webkitConnection) {
        var speed = navigator.webkitConnection.downlink;
        console.log(speed + 'Mbps');
    } else {
        console.log('Internet speed not supported by browser');
    }
}

// Function to check internet connectivity status
function checkConnectivity() {
    // Check for browser support of addEventListener method
    const logStatus = () => console.log(navigator.onLine ? 'Online' : 'Offline');
  
    if (window.addEventListener) {
      window.addEventListener('online', logStatus);
      window.addEventListener('offline', logStatus);
    } else if (window.attachEvent) {
      window.attachEvent('ononline', logStatus);
      window.attachEvent('onoffline', logStatus);
    } else {
      window.ononline = logStatus;
      window.onoffline = logStatus;
    }
}

/**
 * Copies the value of the specified input element to the clipboard.
 *
 * @param {string} from - A CSS selector for the input element.
 */
const inputCopy = (from) => {
    const input_copy = document.querySelector(from).value;
    navigator.clipboard.writeText(input_copy);
    document.querySelector(from).focus();
}

if (document.querySelector("[button-copy]")) {
  // Get all elements with the data-copy attribute
  const copyElements = document.querySelectorAll('[button-copy]');
  // Loop through each element
  copyElements.forEach(copyElement => {
    const copyFrom = copyElement.getAttribute('data-name');

    // Set up a click event listener on the element
    copyElement.addEventListener('click', () => {
      const copyInput = document.querySelector('input[name=' + copyFrom + ']');
      console.log(copyInput.value);
      // Copy the value to the clipboard
      if (navigator.clipboard) {
        navigator.clipboard.writeText(`${copyInput.value}`);
      }else{
        copyInput.select();
        document.execCommand('copy');
      }
      alert('Your profile link has been copied to your clipboard. You can now share it with others');
    });
  });
}

/**
 * Loads a JavaScript file.
 *
 * @param {string} FILE_URL - The URL of the JavaScript file.
 * @param {boolean} [async=true] - Indicates whether the script should be loaded asynchronously.
 */
const loadJS = (FILE_URL, async = true) => {
    const scriptEle = document.createElement("script");
  
    scriptEle.setAttribute("src", FILE_URL);
    scriptEle.setAttribute("type", "text/javascript");
    scriptEle.setAttribute("async", async);
  
    document.body.appendChild(scriptEle);
  
    scriptEle.addEventListener("load", () => {
      console.log("File loaded");
    });
    scriptEle.addEventListener("error", (ev) => {
      console.log("Error on loading file", ev);
    });
}

/**
 * @param mixed filepath
 * 
 * @return [type]
 */
function downloadFile(filepath) {
    const link = document.createElement("a");
    link.href = filepath;
    link.download = filepath.substring(filepath.lastIndexOf("/") + 1);
    document.body.appendChild(link);
    link.click();
    link.remove();
}

/**
 * Returns a boolean indicating whether the current page is active (visible).
 *
 * @return {boolean}
 */
const isPageActive = () => {
    document.addEventListener("visibilitychange", function (ev) {
      const state = document.visibilityState;
      if (state === "visible") {
        return true;
      } else if (state === "hidden") {
        return false;
      }
    });
}

/**
 * Displays a countdown timer until the specified date.
 *
 * @param {string} dt - The end date in the format "YYYY/MM/DD".
 * @param {string} id - The ID of the element to display the countdown timer.
 */
const DateCountDown = (dt, id) => {
    const end = new Date(dt);
    let timer;
  
    const showRemaining = () => {
      const now = new Date();
      const distance = end - now;
      if (distance < 0) {
        clearInterval(timer);
        document.getElementById(id).innerHTML = "HOLD ON!";
  
        return;
      }
      const days = Math.floor(distance / _day);
      const hours = Math.floor((distance % _day) / _hour);
      const minutes = Math.floor((distance % _hour) / _minute);
      const seconds = Math.floor((distance % _minute) / _second);
  
      document.getElementById(id).innerHTML = days + " Days ";
      document.getElementById(id).innerHTML += hours + " Hrs ";
      document.getElementById(id).innerHTML += minutes + " Mins ";
      document.getElementById(id).innerHTML += seconds + " Secs ";
    }
  
    timer = setInterval(showRemaining, 1000);
}

if (document.querySelector("#countdown")) {

  const countdownEl = document.getElementById('countdown');
  const endDateAttr = countdownEl.getAttribute('end-date');
  const endDate = new Date(endDateAttr).getTime();

  const updateCountdown = setInterval(() => {
    const now = new Date().getTime();
    const distance = endDate - now;

    const days = Math.floor(distance / (1000 * 60 * 60 * 24));
    const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((distance % (1000 * 60)) / 1000);

    countdownEl.textContent = `${days}d ${hours}h ${minutes}m ${seconds}s`;

    if (distance < 0) {
      clearInterval(updateCountdown);
      countdownEl.textContent = 'ENDED';
    }
  }, 1000);


}



/**
 * Configures and adds event listeners to elements with the `tush-uploader` class.
 * These elements should contain a file input element with the `uploader-file` attribute
 * and a trigger element with the `uploader-trigger` attribute. The trigger element, when clicked,
 * will open the file input element for the user to select a file. When a file is selected,
 * the `uploader-preview` element's `img` element will display a preview of the selected file.
 * The `uploader-width` and `uploader-height` attributes of the `tush-uploader` element can be used
 * to set the width and height of the element, respectively.
 */
if (document.querySelector(".tush-uploader")) {
    document.querySelectorAll(".tush-uploader").forEach((el) => {
      const box_width = el.getAttribute("uploader-width");
      const box_height = el.getAttribute("uploader-height");
  
      el.removeAttribute("hidden");
      el.style.width = box_width;
      el.style.height = box_height;
      el.style.border = "1.5px dashed rgba(0, 0, 0, 0.1)";
      el.style["padding"] = "10px 15px";
      el.style["cursor"] = "pointer";
      el.style["align-items"] = "center";
      el.style["text-align"] = "center";
      el.style["border-radius"] = "5px";
      el.style["overflow"] = "hidden";
  
      el.querySelector(".uploader-preview").style["margin"] = "5px 2px";
      el.querySelector("img").style.width = "80px";
      el.querySelector("img").style.height = "80px";
      el.querySelector("img").style["border-radius"] = "5px";
      el.querySelector("img").style["z-index"] = "10";
  
      el.querySelector("[uploader-trigger]").addEventListener("click", (event) => {
        event.preventDefault();
        el.querySelector("input[uploader-file]").click();
      });
  
      el.querySelector("[uploader-file]").addEventListener("change", (event) => {
        event.preventDefault();
        const image_preview = el.querySelector(".uploader-preview img");
        const fileReader = new FileReader();
        fileReader.onload = function () {
          image_preview.src = fileReader.result;
        };
        fileReader.readAsDataURL(event.target.files[0]);
      });
    });
}

/**
 * Returns a boolean indicating whether the given string is empty.
 *
 * @param {string} str - The string to check.
 * @return {boolean}
 */
const isEmpty = (str) => {
    return !str || str.length === 0 || str == null || str === "";
}
  
/**
 * Generates a random string of the specified length.
 *
 * @param {number} length - The length of the string to generate.
 * @return {string}
 */
const randTXT = (length) => {
    let result = "";
    const characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    const charactersLength = characters.length;
    for (let i = 0; i < length; i++) {
      result += characters.charAt(Math.floor(Math.random() * charactersLength));
    }
    return result;
}

/**
 * Adds event listeners to elements with the `num` class to only allow numeric input.
 */
document.querySelectorAll(".num").forEach((el) => {
    const events = ["change", "keyup", "paste", "blur"];
    for (const event of events) {
      el.addEventListener(event, (ev) => {
        el.value = el.value.replace(/[^0-9.]/g, "").replace(/(\..*)\./g, "$1");
      });
    }
});

/**
 * Adds an event listener to elements with the `check-all-box` class to allow the user to
 * select all checkboxes on the page with a single checkbox. Also enables or disables the
 * `bulk-action` select element and `bulk-action-btn` button element based on whether or not any checkboxes are checked.
 */

document.querySelectorAll(".check-all-box").forEach((el) => {
    el.addEventListener("change", (ev) => {
      const checkboxClass = ev.target.getAttribute("class");
  
      const _checkboxes = document.querySelectorAll(`input[type=checkbox]:not(${checkboxClass})`);
      for (let i = 0; i < _checkboxes.length; i++) {
        _checkboxes[i].checked = ev.target.checked;
      }
  
      const bulk_action = document.querySelector('.bulk-action');
  
      if (ev.target.checked && bulk_action) {
        bulk_action.disabled = false;
        document.querySelector('.bulk-action-btn').disabled = false;
      } else {
        if (bulk_action) {
          bulk_action.disabled = true;
          document.querySelector('.bulk-action-btn').disabled = true;
        }
      }
    });
});

/**
 * Adds event listeners to elements with the `currency` class to only allow numeric input
 * and format the input as a currency.
 */
document.querySelectorAll(".currency").forEach((el) => {
    const events = ["change", "keyup", "paste", "blur"];
    for (const event of events) {
      el.addEventListener(event, (ev) => {
        el.value = el.value.replace(/[^0-9.]/g, "").replace(/(\..*)\./g, "$1");
        el.value = (parseFloat(el.value) || 0).toFixed(2);
      });
    }
});

function currencyInput(txt, evt) {
    var charCode = (evt.which) ? evt.which : evt.keyCode;
  
    if (charCode == 46 || charCode == 44) {
      //Check if the text already contains the . or , character
      if (txt.value.indexOf('.') === -1 || txt.value.indexOf(',') === -1) {
        return true;
      } else {
        return false;
      }
    }
  
    if (charCode > 31 && (charCode < 48 || charCode > 57)) {
      return false;
    }
  
    if (txt.value.length > 0) {
      var valueInt = removeNonNumeric(txt.value);
      var value = Number(valueInt).toLocaleString();
      txt.value = value;
    }
  
    return true;
}

function addOptionsToSelect(selectElement, options) {
    for (let option of options) {
      const newOption = new Option(option.text, option.value);
      selectElement.add(newOption);
    }
  }
  
function removeNonNumeric(str) {
    var onlyIntegers = str.replace(/[^0-9]/g, '');
    return parseInt(onlyIntegers);
}

function percentageAddition(event, sourceId, targetId, isCurrency = true) {
    let source = document.querySelector(sourceId);
    let target = document.querySelector(targetId);
  
    let sourceNumber = Number(source.value.replace(/[^0-9]/g, ''));
  
    let keydownValue = parseFloat(Number(event.target.value)) || 0;
    let sourceValue = parseFloat(sourceNumber) || 0;
    let calculatedValue = sourceValue + (sourceValue * (keydownValue / 100));
  
    target.value = isCurrency == false ? calculatedValue : Number(calculatedValue).toLocaleString();
}

function calculatePercentage(event, sourceId, targetId, currencyFormat = true) {
    let source = document.querySelector(sourceId);
    let target = document.querySelector(targetId);
    let eventValue = removeNonNumeric(event.target.value);
  
    let sourceNumber = Number(source.value.replace(/[^0-9]/g, ''));
  
    let keydownValue = parseFloat(Number(eventValue)) || 0;
    let sourceValue = parseFloat(sourceNumber) || 0;
    let calculatedValue = getPercentageDifference(keydownValue, sourceValue);
  
    target.value = parseFloat(calculatedValue);
  
    if (currencyFormat == true) {
  
      event.target.value = keydownValue.toLocaleString();
    }
}

function detectElement(element) {
    if (element.nodeName === 'INPUT' || element.nodeName === 'SELECT' || element.nodeName === 'TEXTAREA') {
      return true;
    } else {
      return false;
    }
}

/**
 * Adds event listeners to elements with the `text-length` class to limit the number of
 * characters that can be entered in the element. The number of characters allowed is
 * determined by the element's `data-length` attribute.
 */
document.querySelectorAll(".text-length").forEach((el) => {
    const events = ["change", "keyup", "paste", "blur"];
    for (const event of events) {
      el.addEventListener(event, (ev) => {
        const len = el.getAttribute("data-length");
        el.value = el.value.substr(0, len);
      });
    }
});

/**
 * Returns `true` if the given `value` exists in the given `array`, or `false` otherwise.
 * @param {*} value - The value to search for.
 * @param {Array} array - The array to search in.
 * @returns {boolean} - Whether the value exists in the array.
 */
function isInArray(value, array) {
    return array.indexOf(value) > -1;
}

/**
 * Clears the value of the element with the given `target` selector.
 * @param {string} target - The selector of the element to clear the value of.
 */
function clearValue(target) {
    document.querySelector(target).value = "";
}
  

async function screenAwake(status = true) {
  if ("wakeLock" in navigator) {
      if (status === true) {
          try {
              screenLock = await navigator.wakeLock.request("screen");
          } catch (err) {
              console.log(err.name, err.message);
          }
          return screenLock;
      } else {
          screenLock.release().then(() => {
              console.log("Lock released 🎈");
              screenLock = null;
          });
      }
  } else {
      console.log("Wake lock is not supported by this browser.");
  }
}

