function getPercentageDifference(num1, num2) {
    let largerNum = Math.max(num1, num2);
    let smallerNum = Math.min(num1, num2);
    let difference = largerNum - smallerNum;
    
    return parseFloat((difference / smallerNum) * 100);
}

function isGreaterThanZero(value) {
    if(value === undefined || isNaN(value))
      return false;
    else return value > 0;
}

function readOnly(inputs, action = true) {
  let elem = inputs.elements;
  for (var i = 0, len = elem.length; i < len; ++i) {
      elem[i].readOnly = action;
  }
}

function progressBar(percent) {
  var bar = document.querySelector(".progress-bar");
  bar.style.width = percent + "%";
  bar.setAttribute("aria-valuenow", percent);
}

function isRequiredEmpty(elem) {
  var value_elem = !elem.value || elem.value.length === 0 || elem.value == null || elem.value === "";
  if (elem.hasAttribute("required") && value_elem == true) {
      return true;
  }

  return false;
}


/**
 * Returns the value of the URL parameter with the given `sParam` name.
 * If the parameter does not exist, returns `false`.
 * @param {string} sParam - The name of the URL parameter.
 * @returns {string|boolean} - The value of the URL parameter, or `false` if it does not exist.
 */
function urlParam(sParam) {
    let sPageURL = window.location.search.substring(1);
    let sURLVariables = sPageURL.split("&");
    let sParameterName;
    for (let i = 0; i < sURLVariables.length; i++) {
        sParameterName = sURLVariables[i].split("=");
        if (sParameterName[0] === sParam) {
            return typeof sParameterName[1] === "undefined" ? true : decodeURIComponent(sParameterName[1]);
        }
    }
    return false;
}

function ageRange(from, to) {
  var years = [];
  var from_date = new Date();
  from_date.setFullYear(from_date.getFullYear() - from);
  var _from = from_date.getFullYear();

  var to_date = new Date();
  to_date.setFullYear(to_date.getFullYear() - to);
  var _to = to_date.getFullYear();

  while (_to <= _from) {
      years.push(_to++);
  }
  return years;
}

function removeOptions(selectElement) {
  var i,
      L = selectElement.options.length - 1;
  for (i = L; i >= 0; i--) {
      selectElement.remove(i);
  }
}

function addOptions(container, txt, val) {
  var elem = document.createElement("option");
  elem.textContent = txt;
  elem.value = val;
  container.add(elem);
}

function sureModal(text) {
  let sureDiv = document.createElement("div");
  sureDiv.classList.add("modal", "fade");
  sureDiv.style.backgroundColor = "#00000070";
  sureDiv.setAttribute("id", "sureModal");
  sureDiv.setAttribute("tabindex", "-1");
  sureDiv.setAttribute("aria-labelledby", "sureModalLabel");
  sureDiv.setAttribute("aria-hidden", "true");
  sureDiv.innerHTML = `<div class="modal-dialog modal-dialog-centered"> <div class="modal-content py-5 shadow-sm"> <div class="modal-body py-5 text-center"> <img width="80" src="${baseurl()}/assets/web/images/modal/warning.png" class="img-fluid mx-auto mb-4"/> <h3 class="mb-4 fw-bold">Are You Sure ?</h3> <p class="mb-0 h5">${text}</p></div><div class="modal-footer mx-auto border-top-0"> <button button type="button" class="btn btn-primary rounded-4 modal-confirm fs-6 px-5" data-bs-dismiss="modal">Proceed!</button> <button type="button" class="btn btn-danger rounded-4 modal-cancel fs-6 px-5" data-bs-dismiss="modal">Return</button> </div></div></div>`;

  document.body.appendChild(sureDiv);
  const sureModal = new bootstrap.Modal(document.getElementById("sureModal"), {
      keyboard: false,
      backdrop: "static",
  });
  sureModal.show();

  document.getElementById("sureModal")?.addEventListener("shown.bs.modal", (event) => {
      const otherModal = bootstrap.Modal.getInstance(document.querySelector(".modal:not(#sureModal)"));
      if (!isEmpty(otherModal)) {
          otherModal.hide();
      }
  });

  document.getElementById("sureModal")?.addEventListener("hidden.bs.modal", (event) => {
      sureModal.hide();
      event.target.remove();
  });
}

function popModal(response, texts, btnTxt = "Close", other_btn = false) {
  var btn_press,
      modalTitle,
      btnSecond = ``;
  let img_src = `${baseurl()}/assets/web/images/modal/${response}.png`;

  if (response == "success") {
      modalTitle = "Processing Completed!";
      btn_press = "btn-success text-white";
  } else if (response == "info") {
      modalTitle = "Be knowledgeable!";
      btn_press = "btn-info text-white";
  } else if (response == "warning") {
      modalTitle = "Opps, So Sorry";
      btn_press = "btn-warning text-white";
  } else {
      modalTitle = "Unable to Process!";
      btn_press = "btn-danger text-white";
  }

  if (other_btn != false) {
      btnSecond = `<button button type="button" class="btn btn-dark rounded-4 btn-other fs-6 px-5 mb-2">${other_btn}</button>`;
  }

  
  let popDiv = document.createElement("div");
  popDiv.classList.add("modal", "fade");
  popDiv.style.backgroundColor = "#00000080";
  popDiv.setAttribute("id", "popModal");
  popDiv.setAttribute("tabindex", "-1");
  popDiv.setAttribute("aria-labelledby", "popModalLabel");
  popDiv.setAttribute("aria-hidden", "true");

  popDiv.innerHTML = `<div class="modal-dialog modal-dialog-centered modal-md"> <div class="modal-content py-5 shadow-sm"> <div class="modal-body py-5 text-center"> <img width="80" src="${img_src}" class="img-fluid mx-auto mb-4"/> <h3 class="mb-4 fw-bold">${modalTitle}</h3> <p class="mb-0 fw-normal">${texts}</p></div><div class="modal-footer border-top-0 mx-auto d-grid">${btnSecond}<button type="button" class="btn ${btn_press} rounded-4 modal-btn fs-6 px-5" data-bs-dismiss="modal">${btnTxt}</button></div></div></div>`;

  document.body.appendChild(popDiv);
  const popModal = new bootstrap.Modal(document.getElementById("popModal"), {
      keyboard: false,
      backdrop: "static",
  });
  popModal.show();

  document.getElementById("popModal")?.addEventListener("shown.bs.modal", (event) => {
      const otherModal = bootstrap.Modal.getInstance(document.querySelector(".modal:not(#popModal)"));
      if (!isEmpty(otherModal)) {
          otherModal.hide();
      }
  });

  document.getElementById("popModal")?.addEventListener("hidden.bs.modal", (event) => {
      popModal.hide();
      event.target.remove();
  });
}

function loadingModal(texts = null) {
  let txt = isEmpty(texts) ? "Your request is currently being processed." : texts;
  let loadDiv = document.createElement("div");
  loadDiv.classList.add("modal", "fade");
  loadDiv.style.backgroundColor = "#00000070";
  loadDiv.setAttribute("id", "modalLoading");
  loadDiv.setAttribute("tabindex", "-1");
  loadDiv.setAttribute("aria-labelledby", "modalLoadingLabel");
  loadDiv.setAttribute("aria-hidden", "true");

  loadDiv.innerHTML = `<div class="modal-dialog modal-md modal-dialog-centered"> <div class="modal-content rounded-4 shadow py-5"> <div class="modal-body"> <div class="text-center py-5"> <div class="spinner-border text-warning" style="width: 4rem; height: 4rem;" role="status"> <span class="visually-hidden"></span> </div><h3 class="fw-bold">Please Wait!</h3> <p class="mb-2 mt-2 fw-normal">${txt}</p><h6 class="fw-bold load-percent"></h6> <div class="placeholder-glow mt-3"> <span class="placeholder rounded-pill text-warning col-4"></span> <span class="placeholder rounded-pill text-warning col-4"></span> <span class="placeholder rounded-pill bg-warning text-warning col-5"></span><span class="placeholder rounded-pill bg-warning text-warning col-2"></span><span class="placeholder rounded-pill bg-primary col-6"></span> </div></div></div></div></div>`;

  document.body.appendChild(loadDiv);
  const modalLoading = new bootstrap.Modal(document.getElementById("modalLoading"), {
      keyboard: false,
      backdrop: "static",
  });
  modalLoading.show();

  document.getElementById("modalLoading")?.addEventListener("shown.bs.modal", (event) => {
      const otherModal = bootstrap.Modal.getInstance(document.querySelector(".modal:not(#modalLoading)"));
      if (!isEmpty(otherModal)) {
          otherModal.hide();
      }
  });
}

