async function postForm(url, form, timeout = false) {
    // Create an AbortController instance to allow request cancellation
    const controller = new AbortController();
  
    // Set timeout if specified
    if (timeout) {
      setTimeout(() => controller.abort(), timeout);
    }
  
    // Convert form data to URL-encoded query string format
    const formData = new URLSearchParams(new FormData(form));
  
    try {
      // Send POST request with form data
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Cache-Control": "no-cache",
          "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
        },
        body: formData,
        credentials: "same-origin",
        cache: "no-cache",
        signal: controller.signal,
      });
  
      // Check that the response was successful
      if (!response.ok) {
        const message = `An error has occurred: ${response.status}`;
        throw new Error(message);
      }
  
      // Parse the response body as JSON
      const responseBody = await response.text();
      console.log(responseBody);
      return JSON.parse(responseBody);
    } catch (error) {
      // Handle cancellation error and log other errors
      if (error.name === "AbortError") {
        console.log("Process Abort:");
        hideLoad();
      } else {
        console.log("Fetch error:", error);
      }
    }
  }

async function postData(url, body = {}, timeout = 45000) {
    const controller = new AbortController();
  // 20 second timeout:
  const timeoutId = setTimeout(() => controller.abort(), timeout);

  try {
      const response = await fetch(url, {
          method: "POST",
          headers: new Headers({
              Accept: "application/json",
              "Cache-Control": "no-cache",
              "Content-Type": "application/json; charset=UTF-8",
          }),
          body: JSON.stringify(body),
          credentials: "include",
          cache: "no-cache",
          signal: controller.signal,
      });

      if (!response.ok) {
          // const message = `An error has occured: ${response.status}`;
          // throw new Error(message);
          return response.text().then((text) => {
              throw text;

              // if the error is an object and you just want to display some elements:
              //throw JSON.parse(text);
          });
      } else {
          clearTimeout(timeoutId);
          return await response.json();
      }
  } catch (error) {
      if (error.name === "AbortError") {
          hideLoad();
      } else {
          console.log("Fetch error: ", error);
      }
  }
}

async function getData(url = "", is_json = true) {
  try {
      const response = await fetch(url, {
          method: "GET",
          mode: "cors", // no-cors, *cors, same-origin
          cache: "no-cache",
          headers: {
              "Cache-Control": "no-cache",
              "Content-Type": "application/json; charset=UTF-8",
          },
          signal: controller.signal,
      });

      if (!response.ok) {
          const message = `An error has occured: ${response.status}`;
          throw new Error(message);
      }

      if (is_json == true) {
          return await response.json();
      } else {
          return await response.text();
      }
  } catch (error) {
      if (error.name === "AbortError") {
          hideLoad();
      } else {
          console.log("Fetch error: ", error);
      }
  }
}

async function xhrData(url = "", data, is_json = false, is_loading = false, timeout = false) {
    try {
        const xhr = new XMLHttpRequest();
        xhr.open("POST", url, true);

        if (is_loading) {
            xhr.upload.onprogress = (event) => {
                if (event.lengthComputable) {
                    let percentComplete = (event.loaded / event.total) * 100;
                    document.querySelector(".load-percent").innerHTML = `${percentComplete}%`;
                } else {
                    let percentComplete = event.loaded;
                    document.querySelector(".load-percent").innerHTML = `${percentComplete}%`;
                }
            };
        }

        xhr.onerror = (evt) => {
            console.log(`Unable to make request: ${evt}`);
        };

        xhr.onreadystatechange = () => {
            if (xhr.readyState == 3 && is_loading) {
                document.querySelector(".load-percent").innerHTML = "0%";
            }
            if (xhr.readyState !== 4) {
                return;
            }
        };

        if (is_json) {
            xhr.responseType = "assets/json";
            xhr.setRequestHeader("Content-type", "application/json; charset=utf-8");
        }
        xhr.setRequestHeader("Cache-Control", "no-cache");

        if (timeout) {
            xhr.timeout = timeout;
            xhr.ontimeout = function () {
                alert("Timed out!!!");
            };
        }

        xhr.send(data);

        const response = await new Promise((resolve, reject) => {
            xhr.onload = () => {
                if (xhr.status == 200) {
                    console.log(xhr.response);
                    if (is_json) {
                        resolve(xhr.response);
                    } else {
                        resolve(JSON.parse(xhr.response));
                    }
                } else {
                    console.log(`Error ${xhr.status}: ${xhr.statusText}`);
                    reject(new Error(`Error ${xhr.status}: ${xhr.statusText}`));
                }
            };
        });

        return response;
    } catch (error) {
        console.log(error);
        throw error;
    }
}
  

